"use strict";
const state = {user:null,csrf:"",page:"overview",tickets:[],filter:"all",search:"",selected:null,seq:0,busy:false,replyMode:"auto",live:"connecting",refreshPending:false,profileOpen:false};
state.timeZone=sessionStorage.getItem("lumen.timeZone")||Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC";
